import { transaction } from '../../../packages/database/src/pool.js';
import { logger } from '../../../packages/observability/src/logger.js';
import {
  claimJob,
  completeJob,
  failJob,
  recoverExpiredJobLeases,
  type ClaimedJob,
} from '../../../packages/operations/src/job-lifecycle.js';
import { CustomerNotFoundForErasureError, eraseCustomerData } from './erasure-executor.js';
import { ErasureRepository } from './erasure-repository.js';

export const ERASURE_QUEUE = 'privacy-erasure';

type ErasureJobPayload = { requestId: string; merchantId: string; customerId: string };

const repository = new ErasureRepository();

/** Maps failures to a stable, customer-data-free error code safe to expose via the status API. */
function errorCode(error: unknown): string {
  if (error instanceof CustomerNotFoundForErasureError) return 'customer_not_found';
  return 'erasure_processing_failed';
}

async function processOne(job: ClaimedJob<ErasureJobPayload>): Promise<void> {
  await transaction(async (client) => {
    await repository.markProcessing(client, job.payload.requestId);
  });
  try {
    await transaction(async (client) => {
      await eraseCustomerData(client, job.payload.merchantId, job.payload.customerId);
      await repository.markCompleted(client, job.payload.requestId);
      await completeJob(client, job);
    });
  } catch (error) {
    await transaction(async (client) => {
      await repository.markFailed(client, job.payload.requestId, errorCode(error));
      await failJob(client, job, error);
    });
  }
}

export async function runErasureWorker(signal: AbortSignal): Promise<void> {
  const workerId = `erasure-worker-${randomUUID()}`;
  let lastLeaseRecovery = 0;
  while (!signal.aborted) {
    if (Date.now() - lastLeaseRecovery > 30_000) {
      await recoverExpiredJobLeases(ERASURE_QUEUE);
      lastLeaseRecovery = Date.now();
    }
    const job = await claimJob<ErasureJobPayload>(ERASURE_QUEUE, workerId);
    if (!job) { await new Promise((resolve) => setTimeout(resolve, 250)); continue; }
    try {
      await processOne(job);
    } catch (error) {
      logger.error({ error, jobId: job.id }, 'erasure job failed unexpectedly');
    }
  }
}
"}

{"command":"create","path":"/workspace/source/apps/customer-service/src/erasure-service.ts","file_text":"import { transaction } from '../../../packages/database/src/pool.js';
import { completeIdempotency, requestHash, reserveIdempotency } from '../../payment-service/src/idempotency.js';
import { CustomerRepository } from './repository.js';
import { ERASURE_QUEUE } from './erasure-worker.js';
import { ErasureRepository, type ErasureRequestRow } from './erasure-repository.js';

const IDEMPOTENCY_SCOPE = 'erasure-request';

export interface ErasureRequestBody {
  id: string;
  customerId: string;
  status: ErasureRequestRow['status'];
  attempts: number;
  createdAt: string;
  updatedAt: string;
  completedAt: string | null;
  lastError: string | null;
}

function toBody(row: ErasureRequestRow): ErasureRequestBody {
  return {
    id: row.id,
    customerId: row.customer_id,
    status: row.status,
    attempts: row.attempts,
    createdAt: row.created_at.toISOString(),
    updatedAt: row.updated_at.toISOString(),
    completedAt: row.completed_at ? row.completed_at.toISOString() : null,
    lastError: row.last_error,
  };
}

export class ErasureService {
  constructor(
    private readonly repository = new ErasureRepository(),
    private readonly customers = new CustomerRepository(),
  ) {}

  async requestErasure(merchantId: string, customerId: string, idempotencyKey: string): Promise<{ status: number; body: ErasureRequestBody }> {
    const customer = await this.customers.find(merchantId, customerId);
    if (!customer) throw Object.assign(new Error('customer_not_found'), { statusCode: 404 });

    const hash = requestHash({ customerId });
    const result = await transaction(async (client) => {
      const replay = await reserveIdempotency(client, merchantId, IDEMPOTENCY_SCOPE, idempotencyKey, hash);
      if (replay) return { body: replay.body as ErasureRequestBody, status: replay.status, fresh: false };

      const existing = await this.repository.findByCustomer(merchantId, customerId);
      if (existing) {
        await this.repository.reviveJobIfDead(client, existing.job_id);
        const body = toBody(existing);
        await completeIdempotency(client, merchantId, IDEMPOTENCY_SCOPE, idempotencyKey, 202, body);
        return { body, status: 202, fresh: false };
      }

      const created = await this.repository.create(client, merchantId, customerId);
      const job = await client.query<{ id: string }>(
        `INSERT INTO operations.jobs(queue,job_type,merchant_id,payload,max_attempts)
         VALUES($1,'customer.erasure',$2,$3,20) RETURNING id`,
        [ERASURE_QUEUE, merchantId, { requestId: created.id, merchantId, customerId }],
      );
      await this.repository.attachJob(client, created.id, job.rows[0]!.id);
      const body = toBody({ ...created, job_id: job.rows[0]!.id });
      await completeIdempotency(client, merchantId, IDEMPOTENCY_SCOPE, idempotencyKey, 202, body);
      return { body, status: 202, fresh: true };
    });
    return { status: result.status, body: result.body };
  }

  async find(merchantId: string, requestId: string): Promise<ErasureRequestBody | undefined> {
    const row = await this.repository.findById(merchantId, requestId);
    return row ? toBody(row) : undefined;
  }
}
"}

