  }
  if (event.eventType === EVENT_TYPES.CUSTOMER_ERASED && customerId) {
    await searchClient.delete({ index: CUSTOMER_INDEX, id: `${event.merchantId}:${customerId}` }).catch((error: { meta?: { statusCode?: number } }) => {
